import{_ as r,C as n,o as s,c as l,ag as o,E as a}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Bulk Upload","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/bulk-upload.md","filePath":"catalog/bulk-upload.md","lastUpdated":1786088921000}'),i={name:"catalog/bulk-upload.md"};function d(p,t,g,u,c,h){const e=n("ImagePopup");return s(),l("div",null,[t[0]||(t[0]=o('<h1 id="bulk-upload" tabindex="-1">Bulk Upload <a class="header-anchor" href="#bulk-upload" aria-label="Permalink to &quot;Bulk Upload&quot;">​</a></h1><p>Bulk Upload lets a seller add many products at once from a spreadsheet, instead of creating them one by one. Uploads are validated before anything is created, run in the background, and report exactly what happened — so a large catalog can be listed in a single pass.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>The two kinds of bulk upload</li><li>How the upload wizard is structured, step by step</li><li>How an import is validated, run, and reported</li></ul></div><h2 id="the-two-kinds-of-upload" tabindex="-1">The two kinds of upload <a class="header-anchor" href="#the-two-kinds-of-upload" aria-label="Permalink to &quot;The two kinds of upload&quot;">​</a></h2><p>From the Seller Panel, open <strong>Catalog → Bulk Upload</strong>. The <strong>Imports</strong> screen offers two ways to add products in bulk:</p>',5)),a(e,{src:"/images/bulk-upload/imports.png",alt:"Bulk Upload imports screen"}),t[1]||(t[1]=o('<ul><li><strong>List Your Own Products</strong> — bulk-create brand-new products in your catalog from a spreadsheet (with images).</li><li><strong>Sell Catalog Products</strong> — bulk-list products already in the marketplace catalog as your own, at your own price and stock (the bulk version of <a href="/catalog/selling-existing-products">Selling Existing Products</a>).</li></ul><p>Below the cards, <strong>Past Uploads</strong> lists every import with its <strong>type</strong>, <strong>state</strong> (pending / validated / processing / completed), uploaded file, completion time, and a <strong>summary</strong> of created / updated / deleted counts (with an error-file link where relevant).</p><h2 id="creating-an-import-—-the-wizard" tabindex="-1">Creating an import — the wizard <a class="header-anchor" href="#creating-an-import-—-the-wizard" aria-label="Permalink to &quot;Creating an import — the wizard&quot;">​</a></h2><p>Choosing a kind opens a short wizard.</p>',4)),a(e,{src:"/images/bulk-upload/create-source.png",alt:"Bulk upload wizard — Source step"}),t[2]||(t[2]=o('<ol><li><strong>Source</strong> — confirm the <strong>Type</strong>, download a <strong>sample file</strong> in your format (<strong>CSV / XLS / XLSX / XML</strong>) so your columns line up, and upload your <strong>file</strong>.</li><li><strong>Images</strong> <em>(List Your Own Products only)</em> — supply images either as <strong>URLs in the sheet</strong> (recommended) or by uploading a <strong>ZIP</strong> of image files (a sample ZIP is provided).</li><li><strong>Settings</strong> — choose the <strong>Action</strong> (<strong>Create/Update</strong> or <strong>Delete</strong>), the <strong>Validation Strategy</strong> (<strong>Stop on Errors</strong> or <strong>Skip Errors</strong>), the number of <strong>Allowed Errors</strong>, the <strong>Field Separator</strong> (for CSV), and whether to <strong>Process in Background</strong>.</li></ol><p>Finish with <strong>Start Import</strong>, which validates the file and begins.</p><h2 id="validating-and-running" tabindex="-1">Validating and running <a class="header-anchor" href="#validating-and-running" aria-label="Permalink to &quot;Validating and running&quot;">​</a></h2><p>Each upload becomes a record you can reopen at any time. A typical import moves through clear phases (shown as a stepper):</p><ul><li><strong>Validate</strong> — the file is checked before anything is created. You get a verdict — valid, partially valid (bad rows will be skipped, up to your allowed-errors limit), or invalid — with counts of rows processed, invalid rows, and total errors. When there are errors, <strong>Download Full Report</strong> lists exactly what to fix.</li><li><strong>Download Images</strong> <em>(own products)</em> — images referenced in the sheet are fetched up front.</li><li><strong>Create / Assign / Delete</strong> → <strong>Connect</strong> → <strong>Finalize</strong> — valid rows are imported in the background, related products are linked, and prices and stock are finalized, with live progress.</li></ul><p>When it finishes, you get a <strong>&quot;Your import was successful&quot;</strong> summary with <strong>Created / Updated / Deleted</strong> counts, and can download a full processing <strong>report</strong> (records processed, time taken, and so on).</p><h2 id="after-the-upload" tabindex="-1">After the upload <a class="header-anchor" href="#after-the-upload" aria-label="Permalink to &quot;After the upload&quot;">​</a></h2><p>Imported products behave like any other seller product: they appear in <strong>Catalog → Products</strong> and go through the normal <a href="/catalog/product-management#drafts-submission-and-approval">approval flow</a> before reaching the storefront. Adjust stock and pricing afterwards from <a href="/inventory/manage-inventory">Manage Inventory</a> and <a href="/pricing/manage-pricing">Manage Pricing</a>.</p><div class="tip custom-block"><p class="custom-block-title">Always start from the sample</p><p>Download the sample file for your import type and build your sheet from it — matching the expected columns exactly is the quickest way to pass validation on the first try.</p></div>',9))])}const w=r(i,[["render",d]]);export{f as __pageData,w as default};
